    const cors = require('cors');
    const app = express();
    const PORT = 5000;

    // Middleware
    app.use(cors());
    app.use(express.json());

    // Dummy Data (In-Memory Database)
    let users = [
      { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
      { id: 2, name: 'Bob Smith', email: 'bob@example.com' }
